PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE posts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT UNIQUE NOT NULL,
  title TEXT NOT NULL,
  excerpt TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL DEFAULT '',
  cover_image TEXT DEFAULT NULL,
  published INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, category_id INTEGER DEFAULT NULL REFERENCES categories(id) ON DELETE SET NULL);
INSERT INTO "posts" ("id","slug","title","excerpt","body","cover_image","published","created_at","updated_at","category_id") VALUES(1,'welcome-to-my-blog','Welcome to my blog','This is the first post on my new blog powered by Cloudflare Workers.','## Welcome!\n\nThis site is powered by **Cloudflare Workers** and **D1** for a seamless content management experience.\n\n### Why Cloudflare Workers?\n\n- Edge-rendered for global speed\n- Zero egress fees with R2 storage\n- D1 database for instant content updates\n- Custom admin panel for visual editing\n\nStay tuned for more posts!','https://media.paulibaby.com/1788366706734-PA.webp',1,'2026-08-14 15:12:47','2026-09-02 16:31:49',NULL);
INSERT INTO "posts" ("id","slug","title","excerpt","body","cover_image","published","created_at","updated_at","category_id") VALUES(2,'why-i-moved-to-cloudflare','Why I moved to Cloudflare','Speed, simplicity, and edge computing — here''s why I made the switch.','<p>We''re partnering with a well-established organisation at the beginning of an exciting automation and digital transformation journey. Rather than stepping into a large established technology team, you''ll have the opportunity to help shape how the business leverages Microsoft technologies to improve efficiency, accuracy and user experience.</p><p></p>','https://media.paulibaby.com/1788366721354-1072651-HeroBG-1600x616.avif',1,'2026-08-14 15:12:47','2026-09-02 16:32:34',NULL);
